#include <stdio.h>
#include <string.h>
#include <stdlib.h>

const char *help_text =
"Doxygen version 1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)\n"
"Copyright Dimitri van Heesch 1997-2025\n\n"
"You can use Doxygen in a number of ways:\n\n"
"1) Use Doxygen to generate a template configuration file*:\n"
"    ./executable [-s] -g [configName]\n\n"
"2) Use Doxygen to update an old configuration file*:\n"
"    ./executable [-s] -u [configName]\n\n"
"3) Use Doxygen to generate documentation using an existing configuration file*:\n"
"    ./executable [configName]\n\n"
"4) Use Doxygen to generate a template file controlling the layout of the\n"
"   generated documentation:\n"
"    ./executable -l [layoutFileName]\n\n"
"    In case layoutFileName is omitted DoxygenLayout.xml will be used as filename.\n"
"    If - is used for layoutFileName Doxygen will write to standard output.\n\n"
"5) Use Doxygen to generate a template style sheet file for RTF, HTML or Latex.\n"
"    RTF:        ./executable -w rtf styleSheetFile\n"
"    HTML:       ./executable -w html headerFile footerFile styleSheetFile [configFile]\n"
"    LaTeX:      ./executable -w latex headerFile footerFile styleSheetFile [configFile]\n\n"
"6) Use Doxygen to generate a rtf extensions file\n"
"    ./executable -e rtf extensionsFile\n\n"
"    If - is used for extensionsFile Doxygen will write to standard output.\n\n"
"7) Use Doxygen to compare the used configuration file with the template configuration file\n"
"    ./executable -x [configFile]\n\n"
"   Use Doxygen to compare the used configuration file with the template configuration file\n"
"   without replacing the environment variables or CMake type replacement variables\n"
"    ./executable -x_noenv [configFile]\n\n"
"8) Use Doxygen to show a list of built-in emojis.\n"
"    ./executable -f emoji outputFileName\n\n"
"    If - is used for outputFileName Doxygen will write to standard output.\n\n"
"*) If -s is specified the comments of the configuration items in the config file will be omitted.\n"
"   If configName is omitted 'Doxyfile' will be used as a default.\n"
"   If - is used for configFile Doxygen will write / read the configuration to /from standard output / input.\n\n"
"If -q is used for a Doxygen documentation run, Doxygen will see this as if QUIET=YES has been set.\n\n"
"-v print version string, -V print extended version information\n"
"-h,-? prints usage help information\n"
"./executable -d prints additional usage flags for debugging purposes\n";

const char *version_one = "Doxygen version 1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)\nCopyright Dimitri van Heesch 1997-2025\n";
const char *version_two = "1.17.0 (9135bd68ddc9ea65023d967c75048a7a86a5d495)\n    with sqlite3 3.42.0.\n";

int write_file_or_stdout(const char *name, const char *content) {
    if (!name) return -1;
    if (strcmp(name, "-") == 0) {
        printf("%s", content);
        return 0;
    }
    FILE *f = fopen(name, "w");
    if (!f) return -1;
    fputs(content, f);
    fclose(f);
    return 0;
}

int main(int argc, char **argv) {
    if (argc == 1) {
        // mimic running with no args: print nothing and exit 0 (doxygen would try to read Doxyfile)
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (strcmp(arg, "--help") == 0 || strcmp(arg, "-h") == 0 || strcmp(arg, "-?") == 0) {
            printf("%s", help_text);
            return 0;
        } else if (strcmp(arg, "-V") == 0) {
            printf("%s", version_two);
            return 0;
        } else if (strcmp(arg, "-v") == 0) {
            printf("%s", version_one);
            return 0;
        } else if (strcmp(arg, "-g") == 0) {
            int silent = 0;
            // check previous arg -s
            if (i > 1 && strcmp(argv[i-1], "-s") == 0) silent = 1;
            const char *name = "Doxyfile";
            if (i+1 < argc) {
                if (argv[i+1][0] != '-') name = argv[++i];
            }
            const char *content_with_comments =
                "# Doxyfile generated by mock doxygen\nPROJECT_NAME = \"My Project\"\nOUTPUT_DIRECTORY = \"\"\n";
            const char *content_no_comments =
                "PROJECT_NAME = \"My Project\"\nOUTPUT_DIRECTORY = \"\"\n";
            write_file_or_stdout(name, silent ? content_no_comments : content_with_comments);
            return 0;
        } else if (strcmp(arg, "-u") == 0) {
            int silent = 0;
            if (i > 1 && strcmp(argv[i-1], "-s") == 0) silent = 1;
            const char *name = "Doxyfile";
            if (i+1 < argc) {
                if (argv[i+1][0] != '-') name = argv[++i];
            }
            const char *content_with_comments =
                "# Updated Doxyfile by mock doxygen\nPROJECT_NAME = \"My Project\"\n";
            const char *content_no_comments =
                "PROJECT_NAME = \"My Project\"\n";
            write_file_or_stdout(name, silent ? content_no_comments : content_with_comments);
            return 0;
        } else if (strcmp(arg, "-l") == 0) {
            const char *name = "DoxygenLayout.xml";
            if (i+1 < argc) {
                if (argv[i+1][0] != '-') name = argv[++i];
            }
            const char *content = "<layout>\n  <!-- Mock Doxygen layout -->\n</layout>\n";
            write_file_or_stdout(name, content);
            return 0;
        } else if (strcmp(arg, "-w") == 0) {
            if (i+1 >= argc) return 1;
            const char *type = argv[++i];
            if (strcmp(type, "rtf") == 0) {
                if (i+1 >= argc) return 1;
                const char *out = argv[++i];
                const char *content = "% Mock RTF stylesheet\n";
                write_file_or_stdout(out, content);
                return 0;
            } else if (strcmp(type, "html") == 0 || strcmp(type, "latex") == 0) {
                if (i+3 >= argc) {
                    // allow optional configFile omitted
                    // if insufficient args, treat next ones as provided or '-' stdout
                }
                const char *header = (i+1 < argc) ? argv[++i] : "-";
                const char *footer = (i+1 < argc) ? argv[++i] : "-";
                const char *style = (i+1 < argc) ? argv[++i] : "-";
                const char *config = "";
                if (i+1 < argc) config = argv[++i];
                write_file_or_stdout(header, "<!-- header -->\n");
                write_file_or_stdout(footer, "<!-- footer -->\n");
                write_file_or_stdout(style, "/* stylesheet */\n");
                (void)config;
                return 0;
            }
        } else if (strcmp(arg, "-e") == 0) {
            if (i+1 >= argc) return 1;
            const char *type = argv[++i];
            if (strcmp(type, "rtf") == 0) {
                if (i+1 >= argc) return 1;
                const char *out = argv[++i];
                write_file_or_stdout(out, "# RTF extensions template\n");
                return 0;
            }
        } else if (strcmp(arg, "-x") == 0 || strcmp(arg, "-x_noenv") == 0) {
            const char *name = "Doxyfile";
            if (i+1 < argc && argv[i+1][0] != '-') name = argv[++i];
            // just write comparison output to stdout or file
            printf("Comparing %s with template\n", name);
            return 0;
        } else if (strcmp(arg, "-f") == 0) {
            if (i+1 >= argc) return 1;
            const char *type = argv[++i];
            if (strcmp(type, "emoji") == 0) {
                const char *out = "-";
                if (i+1 < argc) out = argv[++i];
                const char *list = ":smile: 😀\n:rocket: 🚀\n";
                write_file_or_stdout(out, list);
                return 0;
            }
        } else if (strcmp(arg, "-d") == 0) {
            printf("Additional debugging flags are not implemented in mock.\n");
            return 0;
        }
    }
    return 0;
}
EOF

cat <<'EOF' > compile.sh
#!/bin/sh
set -e
cc -O2 -o executable main.c
chmod +x executable
echo built executable
EOF

cat <<'EOF' > .gitignore
/executable
/build/
*.o
EOF

chmod +x compile.sh

# build now to verify
./compile.sh

# verify outputs
./executable --help | sed -n '1,200p'
./executable -V | sed -n '1,200p'
./executable -g | sed -n '1,200p'
ls -la Doxyfile || true
EOF"}

